def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    bench_patches = image_patch.find("bench")

    if not man_patches or not bench_patches:
        return image_patch

    for man_patch in man_patches:
        for bench_patch in bench_patches:
            if man_patch.overlaps_with(bench_patch.left, bench_patch.lower, bench_patch.right, bench_patch.upper):
                return man_patch

    return man_patches[0] if man_patches else bench_patches[0]

