def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    horse_patches = image_patch.find("horse")
    if not horse_patches: return image_patch

    top_patches = image_patch.find("pink top")
    if not top_patches: return horse_patches[0]

    top_depth = None
    closest_horse = None
    for horse in horse_patches:
        for top in top_patches:
            if horse.overlaps_with(top.left, top.lower, top.right, top.upper):
                if top_depth is None or horse.compute_depth() < top_depth:
                    top_depth = horse.compute_depth()
                    closest_horse = horse
    return closest_horse if closest_horse else horse_patches[0]

